class GlassDialog{constructor(){this.injectStyles();}
injectStyles(){if(document.getElementById('glass-dialog-styles'))return;const style=document.createElement('style');style.id='glass-dialog-styles';style.textContent=`
      .gd-overlay {
        position: fixed; inset: 0; z-index: 3000;
        display: flex; align-items: center; justify-content: center; padding: 24px;
        background: rgba(0, 0, 0, 0.55);
        backdrop-filter: blur(16px) saturate(150%);
        -webkit-backdrop-filter: blur(16px) saturate(150%);
        opacity: 0; visibility: hidden;
        transition: opacity 0.28s cubic-bezier(0.16, 1, 0.3, 1), visibility 0.28s;
  font-family: var(--font-sans, -apple-system, BlinkMacSystemFont, "SF Pro Text", "Inter", sans-serif);
      }
      .gd-overlay.active { opacity: 1; visibility: visible; }

      .gd-box {
        width: 100%; max-width: 400px;
        background: var(--gd-surface, rgba(24, 28, 40, 0.92));
        border: 1px solid rgba(255, 255, 255, 0.16);
        border-radius: 24px;
        box-shadow: 0 24px 60px rgba(0, 0, 0, 0.55), inset 0 1px 1px rgba(255, 255, 255, 0.14);
        padding: 30px 28px 24px;
        display: flex; flex-direction: column; gap: 14px;
        transform: scale(0.9) translateY(14px); opacity: 0;
        transition: transform 0.34s cubic-bezier(0.34, 1.4, 0.64, 1), opacity 0.24s ease;
        text-align: center;
      }
      .gd-overlay.active .gd-box { transform: scale(1) translateY(0); opacity: 1; }

      [data-theme="light"] .gd-box,
      html[data-theme="light"] .gd-box { background: rgba(255, 255, 255, 0.94); border-color: rgba(0, 0, 0, 0.1); box-shadow: 0 24px 60px rgba(0, 0, 0, 0.18), inset 0 1px 1px rgba(255, 255, 255, 0.9); }

      .gd-icon {
        width: 54px; height: 54px; margin: 0 auto; border-radius: 50%;
        display: flex; align-items: center; justify-content: center;
      }
      .gd-icon svg { width: 28px; height: 28px; }
      .gd-icon.warning { background: rgba(255, 159, 10, 0.15); color: #ff9f0a; }
      .gd-icon.danger  { background: rgba(255, 69, 58, 0.15);  color: #ff453a; }
      .gd-icon.info    { background: rgba(10, 132, 255, 0.15); color: #0a84ff; }
      .gd-icon.success { background: rgba(48, 209, 88, 0.15);  color: #30d158; }

      .gd-title { font-size: 1.2rem; font-weight: 800; letter-spacing: -0.02em; color: #f5f5f7; }
      .gd-text  { font-size: 0.9rem; line-height: 1.6; color: #98989f; text-align: center; }
      html[data-theme="light"] .gd-title, [data-theme="light"] .gd-title { color: #1d1d1f; }
      html[data-theme="light"] .gd-text,  [data-theme="light"] .gd-text  { color: #6e6e73; }

      .gd-actions { display: flex; gap: 10px; margin-top: 8px; }
      .gd-btn {
        flex: 1; padding: 12px 16px; border-radius: 14px; border: 1px solid transparent;
        font-family: inherit; font-size: 0.9rem; font-weight: 700; cursor: pointer;
        transition: transform 0.15s ease, filter 0.15s ease;
      }
      .gd-btn:active { transform: scale(0.96); }
      .gd-btn-confirm { background: #0a84ff; color: #ffffff; box-shadow: 0 6px 18px rgba(10, 132, 255, 0.4); border: none; }
      .gd-btn-confirm:hover { filter: brightness(1.12); }
      .gd-btn-confirm.danger { background: #ff453a; box-shadow: 0 6px 18px rgba(255, 69, 58, 0.4); }
      .gd-btn-confirm.warning { background: #ff9f0a; box-shadow: 0 6px 18px rgba(255, 159, 10, 0.4); }
      .gd-btn-cancel { background: rgba(255, 255, 255, 0.1); color: #f5f5f7; border: 1px solid rgba(255, 255, 255, 0.14); }
      html[data-theme="light"] .gd-btn-cancel, [data-theme="light"] .gd-btn-cancel { background: rgba(0, 0, 0, 0.05); color: #1d1d1f; border-color: rgba(0, 0, 0, 0.1); }
      .gd-btn-cancel:hover { filter: brightness(1.4); }
      html[data-theme="light"] .gd-btn-cancel:hover { filter: brightness(0.95); }
    `;document.head.appendChild(style);}
show(opts={}){const{title='',text='',icon='warning',confirmText='OK',cancelText=null,confirmType='primary'}=opts;return new Promise((resolve)=>{const icons={warning:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>',danger:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>',info:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4"/><path d="M12 8h.01"/></svg>',success:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="20 6 9 17 4 12"/></svg>'};const overlay=document.createElement('div');overlay.className='gd-overlay';overlay.innerHTML=`
        <div class="gd-box" role="alertdialog" aria-modal="true">
          <div class="gd-icon ${icon}">${icons[icon] || icons.info}</div>
          <div class="gd-title">${title}</div>
          ${text ? `<div class="gd-text">${text}</div>` : ''}
          <div class="gd-actions">
            ${cancelText ? `<button class="gd-btn gd-btn-cancel">${cancelText}</button>` : ''}
            <button class="gd-btn gd-btn-confirm ${confirmType}">${confirmText}</button>
          </div>
        </div>
      `;document.body.appendChild(overlay);const close=(result)=>{overlay.classList.remove('active');setTimeout(()=>overlay.remove(),300);document.removeEventListener('keydown',escHandler);resolve(result);};const escHandler=(e)=>{if(e.key==='Escape')close(false);};document.addEventListener('keydown',escHandler);overlay.querySelector('.gd-btn-confirm').addEventListener('click',()=>close(true));const cancelBtn=overlay.querySelector('.gd-btn-cancel');if(cancelBtn)cancelBtn.addEventListener('click',()=>close(false));overlay.addEventListener('click',(e)=>{if(e.target===overlay)close(false);});requestAnimationFrame(()=>overlay.classList.add('active'));});}}
function btnLoading(btn,state){if(!btn)return;if(state){if(btn.dataset.originalHtml!==undefined)return;btn.dataset.originalHtml=btn.innerHTML;btn.disabled=true;btn.style.width=btn.offsetWidth+'px';btn.innerHTML='<span class="btn-spinner" aria-label="Memuat"></span>';}else{if(btn.dataset.originalHtml===undefined)return;btn.innerHTML=btn.dataset.originalHtml;delete btn.dataset.originalHtml;btn.disabled=false;btn.style.width='';}}
window.GlassDialog=new GlassDialog();window.btnLoading=btnLoading;